      <section v-if="!archiveOpen" class="talent-section">
        <div class="talent-section__heading"><span class="room-talents-settings__talent-wallet-icon"><v-icon icon="mdi-circle-multiple-outline" size="25" /></span><div><h3>{{ t('talents.global') }}</h3><p>{{ t('talents.design.globalHint') }}</p></div><v-switch :model-value="snapshot.settings.globalEnabled" :aria-label="t('talents.globalEnabled')" inset color="primary" hide-details density="comfortable" :disabled="service.state.busy" @update:model-value="setting('globalEnabled', !!$event)" /></div>
        <div v-if="snapshot.settings.globalEnabled" class="room-talents-settings__talent-global-controls">
          <v-text-field :model-value="snapshot.settings.maxGlobal" type="number" min="0" :label="t('talents.maxPoints')" variant="outlined" density="comfortable" hide-details :disabled="service.state.busy" @change="setting('maxGlobal', Number(($event.target as HTMLInputElement).value))" />
