          <footer class="talent-tree-card__actions"><v-btn variant="tonal" color="primary" size="small" prepend-icon="mdi-pencil-outline" :aria-label="t('talents.edit')" @click="edit(tree)">{{ t('common.edit') }}</v-btn><v-spacer /><v-menu><template #activator="{ props: menuProps }"><v-btn v-bind="menuProps" icon="mdi-export-variant" variant="text" size="small" :aria-label="t('talents.transfer.exportTree')" :title="t('talents.transfer.exportTree')" :disabled="transfer?.busy"><v-icon icon="mdi-export-variant" /></v-btn></template><v-list density="compact"><v-list-item prepend-icon="mdi-download-outline" :title="t('talents.transfer.downloadJSON')" @click="transfer?.exportTree(tree, 'download')" /><v-list-item prepend-icon="mdi-content-copy" :title="t('talents.transfer.copyJSON')" @click="transfer?.exportTree(tree, 'clipboard')" /></v-list></v-menu><v-btn icon="mdi-eye-outline" variant="text" size="small" :aria-label="t('talents.visibility')" :title="t('talents.visibility')" @click="visibilityTree = tree.id" /><v-btn v-if="tree.currency !== 'global'" icon="mdi-account-cash-outline" variant="text" size="small" :aria-label="t('talents.distribute')" :title="t('talents.distribute')" @click="distribution = tree.id" /><v-menu><template #activator="{ props: menuProps }"><v-btn v-bind="menuProps" icon="mdi-delete-outline" variant="text" size="small" :aria-label="t('talents.archive.actions')" :title="t('talents.archive.actions')" :disabled="service.state.busy" /></template><v-list density="compact"><v-list-item :prepend-icon="tree.archived ? 'mdi-archive-arrow-up-outline' : 'mdi-archive-outline'" :title="t(tree.archived ? 'talents.archive.restore' : 'talents.archive.archive')" @click="setArchived(tree.id, !tree.archived)" /><v-list-item prepend-icon="mdi-delete-outline" :title="t('talents.delete')" base-color="error" @click="requestDelete(tree.id)" /></v-list></v-menu></footer>
