    <div v-if="!archiveOpen" class="room-talents-settings__talent-archives-footer"><v-btn variant="tonal" color="primary" prepend-icon="mdi-archive-outline" @click="archiveOpen = true">{{ t('talents.archive.open') }}<v-chip size="x-small" variant="flat" class="ml-2">{{ archivedCount }}</v-chip></v-btn></div>

    <v-dialog v-model="layoutDialog" :fullscreen="smAndDown" max-width="820" scrollable :transition="smAndDown ? 'dialog-bottom-transition' : 'dialog-transition'" :aria-label="t('talents.chooseLayout')">
      <v-card class="talents-ui talent-popup"><v-card-title class="talent-popup__heading"><span class="talent-popup__icon"><v-icon icon="mdi-source-branch" size="30" /></span><div><div class="talents-ui__eyebrow">{{ t('talents.addTree') }}</div><h2>{{ t('talents.chooseLayout') }}</h2></div><AppCloseButton @click="layoutDialog = false" /></v-card-title><v-divider />
        <v-card-text class="talent-popup__body"><p class="room-talents-settings__talent-layout-intro">{{ t('talents.design.layoutHint') }}</p><div class="room-talents-settings__talent-layout-choices"><button v-for="layout in layouts" :key="layout" type="button" class="room-talents-settings__talent-layout-choice" :aria-label="t('talents.layouts.' + layout)" @click="create(layout)"><TalentTreePreview :layout="layout" /><div><v-icon :icon="layoutIcons[layout]" size="20" /><strong>{{ t('talents.layouts.' + layout) }}</strong></div><p>{{ t('talents.design.layoutDescriptions.' + layout) }}</p><span class="room-talents-settings__talent-layout-arrow"><v-icon icon="mdi-arrow-right" size="18" /></span></button></div><section class="room-talents-settings__talent-import-options"><div><v-icon icon="mdi-file-import-outline" size="24" /><span><strong>{{ t('talents.transfer.importTree') }}</strong><small>{{ t('talents.transfer.completeSettings') }}</small></span></div><v-btn variant="tonal" color="primary" prepend-icon="mdi-file-upload-outline" :disabled="service.state.busy || transfer?.busy" @click="transfer?.openFile()">{{ t('talents.transfer.fileImport') }}</v-btn><v-btn variant="outlined" prepend-icon="mdi-clipboard-text-outline" :disabled="service.state.busy || transfer?.busy" @click="transfer?.openClipboard()">{{ t('talents.transfer.clipboardImport') }}</v-btn></section></v-card-text>
        <v-card-actions class="talent-popup__footer"><v-spacer /><v-btn variant="text" @click="layoutDialog = false">{{ t('common.cancel') }}</v-btn></v-card-actions>
      </v-card>
    </v-dialog>
    <TalentTreeTransfer ref="transfer" :room-id="roomId" :user-id="userId" @imported="layoutDialog = false" />
    <TalentEditor v-if="editing" :key="editing.id" v-model="editorOpen" :room-id="roomId" :user-id="userId" :tree="editing" />

    <v-dialog :model-value="!!distribution" :fullscreen="smAndDown" max-width="620" scrollable :transition="smAndDown ? 'dialog-bottom-transition' : 'dialog-transition'" :aria-label="t('talents.distribute')" @update:model-value="!$event && (distribution = null)">
      <v-card class="talents-ui talent-popup"><v-card-title class="talent-popup__heading"><span class="talent-popup__icon"><v-icon icon="mdi-account-cash-outline" size="30" /></span><div><div class="talents-ui__eyebrow">{{ distributionName }}</div><h2>{{ t('talents.distribute') }}</h2></div><AppCloseButton @click="distribution = null" /></v-card-title><v-divider />
        <v-card-text class="talent-popup__body"><p class="room-talents-settings__talent-dialog-hint">{{ t('talents.design.distributeHint') }}</p><div class="room-talents-settings__talent-member-list"><div v-for="member in snapshot.members" :key="member.userId" class="room-talents-settings__talent-member-row"><span class="talents-ui__avatar" aria-hidden="true">{{ member.name.slice(0, 1).toUpperCase() }}</span><span class="room-talents-settings__talent-member-name">{{ member.name }}</span><div class="room-talents-settings__talent-balance-stepper"><v-btn icon="mdi-minus" variant="text" size="small" :aria-label="t('talents.removePoint') + ' ' + member.name" :disabled="service.state.busy || balance(member.player) === 0" @click="setBalance(member.userId, balance(member.player) - 1)" /><v-text-field :model-value="balance(member.player)" type="number" min="0" variant="plain" density="compact" hide-details :aria-label="t('talents.points') + ' ' + member.name" :disabled="service.state.busy" @change="setBalance(member.userId, Number(($event.target as HTMLInputElement).value))" /><v-btn icon="mdi-plus" variant="text" size="small" :aria-label="t('talents.addPoint') + ' ' + member.name" :disabled="service.state.busy" @click="setBalance(member.userId, balance(member.player) + 1)" /></div></div></div></v-card-text><v-card-actions class="talent-popup__footer"><v-spacer /><v-btn color="primary" variant="flat" @click="distribution = null">{{ t('talents.design.done') }}</v-btn></v-card-actions>
      </v-card>
    </v-dialog>
    <v-dialog :model-value="!!visibilityTree" :fullscreen="smAndDown" max-width="560" scrollable :aria-label="t('talents.visibility')" @update:model-value="!$event && (visibilityTree = null)">
      <v-card class="talents-ui talent-popup"><v-card-title class="talent-popup__heading"><span class="talent-popup__icon"><v-icon icon="mdi-eye-outline" size="30" /></span><div><div class="talents-ui__eyebrow">{{ visibilityName }}</div><h2>{{ t('talents.visibility') }}</h2></div><AppCloseButton @click="visibilityTree = null" /></v-card-title><v-divider /><v-card-text class="talent-popup__body"><p class="room-talents-settings__talent-dialog-hint">{{ t('talents.visibilityHint') }}</p><div class="room-talents-settings__talent-member-list"><div v-for="member in snapshot.members" :key="member.userId" class="room-talents-settings__talent-member-row"><span class="talents-ui__avatar" aria-hidden="true">{{ member.name.slice(0, 1).toUpperCase() }}</span><span class="room-talents-settings__talent-member-name">{{ member.name }}</span><v-chip v-if="member.player.unlockedTreeIds?.includes(visibilityTree!)" size="x-small" color="primary" variant="tonal">{{ t('talents.progression.earned') }}</v-chip><v-btn v-if="visibilityDefinition?.accessMode === 'restricted'" size="small" :variant="member.player.grantedTreeIds?.includes(visibilityTree!) ? 'tonal' : 'text'" :color="member.player.grantedTreeIds?.includes(visibilityTree!) ? 'primary' : undefined" :aria-label="t(member.player.grantedTreeIds?.includes(visibilityTree!) ? 'talents.progression.revoke' : 'talents.progression.grant') + ' ' + member.name" :disabled="service.state.busy" @click="service.mutate({ op: 'access', treeId: visibilityTree!, targetUserId: member.userId, granted: !member.player.grantedTreeIds?.includes(visibilityTree!) })">{{ t(member.player.grantedTreeIds?.includes(visibilityTree!) ? 'talents.progression.revoke' : 'talents.progression.grant') }}</v-btn><span class="room-talents-settings__talent-visibility-label" :class="{ 'room-talents-settings__talent-visibility-label--visible': memberHasAccess(member.player, member.userId) }">{{ t(isHidden(member.userId) ? 'talents.design.hidden' : memberHasAccess(member.player, member.userId) ? 'talents.design.visible' : 'talents.progression.locked') }}</span><v-btn :icon="isHidden(member.userId) ? 'mdi-eye-off-outline' : 'mdi-eye-outline'" variant="tonal" size="small" :color="isHidden(member.userId) ? undefined : 'primary'" :aria-label="t(isHidden(member.userId) ? 'talents.showTree' : 'talents.hideTree') + ' ' + member.name" :aria-pressed="!isHidden(member.userId)" :disabled="service.state.busy" @click="service.mutate({ op: 'visibility', treeId: visibilityTree!, targetUserId: member.userId, visible: isHidden(member.userId) })" /></div></div></v-card-text><v-card-actions class="talent-popup__footer"><v-spacer /><v-btn color="primary" variant="flat" @click="visibilityTree = null">{{ t('talents.design.done') }}</v-btn></v-card-actions></v-card>
    </v-dialog>
    <v-dialog :model-value="!!deleting" max-width="560" :persistent="service.state.busy" :aria-label="t('talents.archive.confirmDelete')" @update:model-value="!$event && (deleting = null)"><v-card class="talents-ui talent-popup"><v-card-title class="talent-popup__heading"><span class="talent-popup__icon"><v-icon icon="mdi-delete-outline" size="28" /></span><div><h2>{{ t('talents.archive.confirmDelete') }}</h2></div></v-card-title><v-card-text class="talent-popup__body"><p class="room-talents-settings__talent-dialog-hint">{{ t('talents.archive.deletePrompt', { name: snapshot.trees.find(tree => tree.id === deleting)?.name ?? '' }) }}</p><p v-if="affected.length" class="room-talents-settings__talent-dialog-hint">{{ t('talents.deleteRefund') }}</p><div v-for="member in affected" :key="member.userId" class="room-talents-settings__talent-member-row"><span class="room-talents-settings__talent-member-name">{{ member.name }}</span><v-chip size="small" variant="tonal">{{ member.global }} {{ t('talents.global') }}</v-chip><v-chip size="small" variant="tonal">{{ member.tree }} {{ t('talents.treePoints') }}</v-chip></div></v-card-text><v-card-actions class="talent-popup__footer"><v-spacer /><v-btn :disabled="service.state.busy" @click="deleting = null">{{ t('common.cancel') }}</v-btn><v-btn color="error" variant="flat" :loading="service.state.busy" @click="remove(deleting!, affected.length > 0)">{{ t('talents.delete') }}</v-btn></v-card-actions></v-card></v-dialog>
  </div>
</template>
<script setup lang="ts">
import AppCloseButton from '@/shared/ui/AppCloseButton.vue';
import { computed, ref, onMounted } from 'vue';
import { useDisplay } from 'vuetify';
import '@/assets/styles/features/rooms/talents/talent-ui.scss';
import TalentTreePreview from '@/features/rooms/components/talents/TalentTreePreview.component.vue';
import { useI18n } from 'vue-i18n';
import { talentRoom } from '@/features/rooms/services/talents.service';
import { talentTreeRows, treeAccessible } from '@shared/rooms/talents';
import { newTalentTree, type TalentTree, type TalentLayout, type TalentSettings, type TalentPlayer, type TalentResult } from '@shared/rooms/talents.types';
import TalentTreeTransfer from '@/features/rooms/components/talents/TalentTreeTransfer.component.vue';
import TalentEditor from '@/features/rooms/components/talents/TalentEditor.component.vue';
import TalentImage from '@/features/rooms/components/talents/TalentImage.component.vue';
const props = defineProps<{ roomId: string; userId: string }>();
const { smAndDown } = useDisplay();
const { t } = useI18n(); const service = talentRoom(props.roomId, props.userId), snapshot = computed(() => service.state.snapshot);
onMounted(() => service.load());
const archiveOpen = ref(false);
const archivedCount = computed(() => snapshot.value?.trees.filter(tree => tree.archived).length ?? 0);
const orderedTrees = computed(() => talentTreeRows(snapshot.value?.trees.filter(tree => !!tree.archived === archiveOpen.value) ?? []));
const visibilityDefinition = computed(() => snapshot.value?.trees.find(tree => tree.id === visibilityTree.value));
function parentPath(tree: TalentTree) { const names: string[] = [], seen = new Set<string>(); let parent = tree.parentTreeId; while (parent && !seen.has(parent)) { seen.add(parent); const candidate = snapshot.value?.trees.find(tree => tree.id === parent); if (!candidate) break; names.unshift(candidate.name); parent = candidate.parentTreeId; } return names.join(' / '); }
const layoutIcons = { classic: 'mdi-family-tree', centered: 'mdi-orbit', free: 'mdi-vector-polyline' };
const distributionName = computed(() => distribution.value === 'global' ? t('talents.global') : snapshot.value?.trees.find(tree => tree.id === distribution.value)?.name ?? '');
const visibilityName = computed(() => snapshot.value?.trees.find(tree => tree.id === visibilityTree.value)?.name ?? '');
const transfer = ref<InstanceType<typeof TalentTreeTransfer>>();
const layouts: TalentLayout[] = ['classic', 'centered', 'free'];
const layoutDialog = ref(false), editorOpen = ref(false), editing = ref<TalentTree>(), distribution = ref<string | null>(null), visibilityTree = ref<string | null>(null), deleting = ref<string | null>(null), affected = ref<NonNullable<TalentResult['resetRequired']>>([]);
function create(layout: TalentLayout) { layoutDialog.value = false; const tree = newTalentTree(crypto.randomUUID(), layout); tree.name = t('talents.newTree'); edit(tree); }
function edit(tree: TalentTree) { editing.value = JSON.parse(JSON.stringify(tree)); editorOpen.value = true; }
function setting(key: keyof TalentSettings, value: boolean | number) { void service.mutate({ op: 'settings', settings: { ...snapshot.value!.settings, [key]: value } }); }
function balance(player: TalentPlayer) { return distribution.value === 'global' ? player.global : player.trees[distribution.value!] ?? 0; }
function setBalance(targetUserId: string, points: number) { void service.mutate({ op: 'balance', targetUserId, points, ...(distribution.value !== 'global' ? { treeId: distribution.value! } : {}) }); }
function memberHasAccess(player: TalentPlayer, userId: string) { return !!visibilityDefinition.value && treeAccessible(visibilityDefinition.value, player, isHidden(userId)); }
function isHidden(id: string) { return snapshot.value?.hidden?.[visibilityTree.value!]?.includes(id) ?? false; }
function requestDelete(treeId: string) { affected.value = []; deleting.value = treeId; }
function setArchived(treeId: string, archived: boolean) { void service.mutate({ op: 'archive', treeId, archived }); }
async function remove(treeId: string, confirmReset: boolean) { const result = await service.mutate({ op: 'delete', treeId, confirmReset }); if (result?.resetRequired) { affected.value = result.resetRequired; deleting.value = treeId; } else if (result) deleting.value = null; }
</script>
<style scoped lang="scss" src="@/assets/styles/features/rooms/talents/room-talents-settings.scss"></style>
